        /// <summary>Block LSMR over a dense <see cref="floatMxN"/> A (tall or square). Forwards into
        /// <see cref="blsmr{TOp}"/> via <see cref="floatDenseOperator"/>.</summary>
        public static BlockSolveInfo blsmr(in floatMxN A, in floatMxN B, ref floatMxN X, int maxIter, float tol)
            => blsmr(new floatDenseOperator(in A), in B, ref X, maxIter, tol);

        /// <summary>Block LSMR over a dense A with default maxIter (A.N_Cols) and tol (Consts.floatSqrtEps).</summary>
        public static BlockSolveInfo blsmr(in floatMxN A, in floatMxN B, ref floatMxN X)
            => blsmr(in A, in B, ref X, A.N_Cols, Consts.floatSqrtEps);
